def house_bowling(rolls: list[int]) -> int:
    total = 0
    i = 0
    for _ in range(9):
        if rolls[i] == 10:
            total += 10 + sum(rolls[i + 1:i + 3])
            i += 1
        elif rolls[i] + rolls[i + 1] == 10:
            total += 10 + sum(rolls[i + 2:i + 3])
            i += 2
        else:
            total += rolls[i] + rolls[i + 1]
            i += 2
    total += sum(rolls[i:])
    return total
